axs[1].set(xlabel='Imposed tip-Y change (N)',ylabel='FBG curvature difference RMS (1/mm)',yscale='log',title='Nonlinear sensor difference');axs[1].axhline(1e-4,color='black',linestyle=':',label='Current assumed sigma');axs[0].legend();axs[1].legend(fontsize=8)
