xyz=np.array([v(rr,'base'+c) for c in 'XYZ']);ax.set_box_aspect(np.maximum(np.ptp(xyz,axis=1),1));ax.set(xlabel='X (mm)',ylabel='Y (mm)',zlabel='Z (mm)',title='Actual centerlines almost overlap');ax.set_ylabel('');ax.text2D(0.90,0.04,'Y (mm)',transform=ax.transAxes,fontsize=9);ax.locator_params(axis='x',nbins=4);ax.locator_params(axis='y',nbins=3);ax.tick_params(labelsize=8);ax.legend(fontsize=8)
